package devicemonitor.presentation.web

// Self-contained and fully offline. The API supplies bounded summaries and paged timeline data.
internal val PLAYER_DEBUGGER_PAGE = """<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Player Debugger · ADB Performance Studio</title>
<style>
  .pd-hero{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;gap:24px}
  .pd-hero-side{display:flex;align-items:center;gap:9px;padding:11px 14px;border:1px solid var(--line);border-radius:999px;color:var(--muted);background:rgba(255,255,255,.025);font:10px/1 ui-monospace,SFMono-Regular,Menlo,monospace}
  .pd-hero-side:before{content:"";width:7px;height:7px;border-radius:50%;background:var(--teal);box-shadow:0 0 0 5px rgba(88,214,199,.08)}
  .pd-layout{display:grid;grid-template-columns:minmax(300px,.7fr) minmax(0,1.3fr);gap:18px;margin-top:28px;align-items:start}
  .pd-stack{display:grid;gap:18px}.pd-card{padding:22px}.pd-sticky{position:sticky;top:86px}
  .pd-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.pd-field{display:grid;gap:7px;min-width:0}.pd-field.span{grid-column:1/-1}
  .pd-field label,.pd-label{color:#c9c4bb;font-size:10px;font-weight:820;letter-spacing:.08em;text-transform:uppercase}
  .pd-field input,.pd-field select{width:100%;min-height:42px;padding:9px 11px;border:1px solid var(--line);border-radius:10px;color:var(--text);background:#111;outline:none}
  .pd-field input:focus,.pd-field select:focus{border-color:rgba(232,182,109,.55);box-shadow:0 0 0 3px rgba(232,182,109,.08)}
  .pd-hint{color:var(--quiet);font-size:10px;line-height:1.5}.pd-divider{height:1px;margin:18px 0;background:var(--line)}
  .pd-signals{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin-top:12px}
  .pd-signal{position:relative;display:flex;align-items:flex-start;gap:10px;min-height:64px;padding:11px;border:1px solid var(--line);border-radius:12px;background:rgba(255,255,255,.02);cursor:pointer;transition:border-color .2s,background .2s,transform .2s}
  .pd-signal:hover{transform:translateY(-1px);border-color:var(--line-strong);background:rgba(255,255,255,.035)}.pd-signal input{position:absolute;opacity:0}
  .pd-check{display:grid;place-items:center;width:20px;height:20px;flex:none;border:1px solid var(--line-strong);border-radius:7px;color:#111;background:#151515;font-size:13px}
  .pd-signal input:checked+.pd-check{border-color:var(--gold);background:var(--gold-bright)}.pd-signal input:checked+.pd-check:after{content:"✓"}
  .pd-signal strong{display:block;color:var(--text);font-size:11px}.pd-signal small{display:block;margin-top:4px;color:var(--quiet);font-size:9px;line-height:1.35}
  .pd-locked{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:10px;padding:10px 11px;border:1px solid rgba(88,214,199,.18);border-radius:11px;color:#bffcf5;background:rgba(88,214,199,.055);font-size:10px}
  .pd-actions{display:flex;gap:8px;margin-top:17px}.pd-actions .studio-button{flex:1;min-height:44px}.pd-message{min-height:18px;margin-top:10px;color:var(--muted);font-size:10px;line-height:1.5}.pd-message.bad{color:var(--red)}
  .pd-status-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.pd-state{color:var(--gold);font:850 10px/1 ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.12em;text-transform:uppercase}
  .pd-progress{height:5px;margin:16px 0 18px;overflow:hidden;border-radius:999px;background:rgba(255,255,255,.06)}.pd-progress>span{display:block;width:8%;height:100%;border-radius:inherit;background:linear-gradient(90deg,var(--violet),var(--teal));transition:width .35s ease}
  .pd-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.pd-kpi{padding:12px;border:1px solid var(--line);border-radius:12px;background:rgba(0,0,0,.2)}.pd-kpi b{display:block;color:var(--text);font-size:20px;letter-spacing:-.04em}.pd-kpi span{display:block;margin-top:4px;color:var(--quiet);font-size:9px;text-transform:uppercase;letter-spacing:.08em}
  .pd-coverage{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;margin-top:13px}.pd-evidence{display:flex;align-items:center;gap:7px;padding:8px;border:1px solid var(--line);border-radius:10px;color:var(--muted);font-size:9px}.pd-evidence i{display:grid;place-items:center;width:17px;height:17px;border-radius:50%;font-style:normal;font-weight:900}.pd-evidence.reported i{color:#d9d2ff;background:rgba(158,140,255,.14)}.pd-evidence.measured i{color:#bffcf5;background:rgba(88,214,199,.13)}.pd-evidence.inferred i{color:#ffe0ad;background:rgba(232,182,109,.13)}.pd-evidence.unavailable i{color:#aaa;background:rgba(255,255,255,.07)}
  .pd-live{display:grid;grid-template-columns:minmax(0,1fr) minmax(220px,.7fr);gap:12px;margin-top:13px}.pd-well{min-height:114px;padding:14px;border:1px solid var(--line);border-radius:14px;background:rgba(0,0,0,.2)}.pd-well-title{color:var(--quiet);font-size:9px;font-weight:800;letter-spacing:.1em;text-transform:uppercase}
  .pd-path{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:15px}.pd-node{padding:8px 10px;border:1px solid rgba(158,140,255,.24);border-radius:10px;color:#d9d2ff;background:rgba(158,140,255,.07);font-size:10px}.pd-arrow{color:var(--quiet)}
  .pd-incident{margin-top:12px;color:var(--muted);font-size:11px;line-height:1.5}.pd-incident strong{display:block;margin-bottom:4px;color:var(--text);font-size:13px}.pd-severity{display:inline-flex;margin-top:10px;padding:5px 7px;border-radius:7px;color:#ffd3d3;background:rgba(255,118,118,.1);font-size:9px;font-weight:850;text-transform:uppercase}
  .pd-toolbar{display:flex;align-items:flex-end;justify-content:space-between;gap:14px;margin-bottom:12px}.pd-history{display:grid;gap:8px}.pd-run{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:12px;padding:12px;border:1px solid var(--line);border-radius:12px;background:rgba(255,255,255,.02);cursor:pointer}.pd-run:hover{border-color:var(--line-strong);background:rgba(255,255,255,.035)}.pd-run strong{display:block;font-size:11px}.pd-run small{display:block;margin-top:4px;color:var(--quiet);font:9px/1.4 ui-monospace,SFMono-Regular,Menlo,monospace}.pd-run-state{color:var(--green);font-size:9px;font-weight:850;text-transform:uppercase}.pd-empty{padding:22px;border:1px dashed var(--line-strong);border-radius:13px;color:var(--quiet);text-align:center;font-size:10px;line-height:1.6}
  .pd-detail{display:none}.pd-detail.show{display:block}.pd-detail-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.pd-player-list{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}.pd-player{padding:7px 9px;border:1px solid var(--line);border-radius:9px;color:var(--muted);background:rgba(255,255,255,.025);font-size:9px}
  .pd-recorder{display:none}.pd-recorder.show{display:block}.pd-recorder-head{display:flex;align-items:flex-end;justify-content:space-between;gap:14px;margin-bottom:14px}.pd-window-controls{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.pd-window-controls select{min-height:36px;padding:7px 9px;border:1px solid var(--line);border-radius:9px;color:var(--text);background:#111}
  .pd-filter-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;margin-bottom:12px}.pd-filter-grid .pd-field input,.pd-filter-grid .pd-field select{min-height:36px;font-size:10px}.pd-range{display:grid;grid-template-columns:auto minmax(90px,1fr) minmax(90px,1fr) auto;align-items:center;gap:9px;margin:12px 0;color:var(--quiet);font-size:9px}.pd-range input{width:100%;accent-color:var(--gold)}
  .pd-lanes{overflow-x:auto;border:1px solid var(--line);border-radius:14px;background:rgba(0,0,0,.2)}.pd-lane{display:grid;grid-template-columns:118px minmax(520px,1fr);min-height:42px;border-bottom:1px solid var(--line)}.pd-lane:last-child{border-bottom:0}.pd-lane-label{display:flex;align-items:center;justify-content:space-between;gap:6px;padding:9px 10px;border-right:1px solid var(--line);color:var(--muted);font-size:9px;font-weight:760}.pd-lane-label b{color:var(--quiet);font:8px/1 ui-monospace,SFMono-Regular,Menlo,monospace}.pd-track{position:relative;min-height:42px;background-image:linear-gradient(90deg,transparent 24.8%,rgba(255,255,255,.035) 25%,transparent 25.2%,transparent 49.8%,rgba(255,255,255,.035) 50%,transparent 50.2%,transparent 74.8%,rgba(255,255,255,.035) 75%,transparent 75.2%)}
  .pd-marker{position:absolute;top:50%;display:grid;place-items:center;width:18px;height:18px;padding:0;border:1px solid currentColor;border-radius:50%;color:var(--violet);background:#17151e;box-shadow:0 0 0 3px rgba(158,140,255,.08);cursor:pointer;transform:translate(-50%,-50%);transition:transform .16s,box-shadow .16s}.pd-marker:hover,.pd-marker.selected{z-index:2;transform:translate(-50%,-50%) scale(1.22);box-shadow:0 0 0 5px rgba(232,182,109,.12)}.pd-marker.reported{color:var(--violet)}.pd-marker.measured{color:var(--teal)}.pd-marker.inferred{color:var(--gold)}.pd-marker.parsed{color:var(--blue)}.pd-marker span{font:800 7px/1 ui-monospace,SFMono-Regular,Menlo,monospace}
  .pd-inspector-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(240px,.55fr);gap:12px;margin-top:12px}.pd-inspector{min-height:150px;padding:14px;border:1px solid var(--line);border-radius:14px;background:rgba(0,0,0,.2)}.pd-inspector h3{margin:7px 0;color:var(--text);font-size:14px}.pd-inspector-meta{color:var(--quiet);font:9px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace}.pd-inspector pre{max-height:190px;margin:10px 0 0;overflow:auto;white-space:pre-wrap;word-break:break-word;color:#c9c4bb;font:9px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace}.pd-evidence-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}.pd-evidence-button{padding:6px 8px;border:1px solid var(--line);border-radius:8px;color:#bffcf5;background:rgba(88,214,199,.06);font-size:9px;cursor:pointer}
  .pd-incident-list{display:grid;gap:10px}.pd-incident-card{padding:15px;border:1px solid var(--line);border-radius:14px;background:rgba(0,0,0,.2)}.pd-incident-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.pd-incident-title{color:var(--text);font-size:13px;font-weight:820}.pd-incident-copy{margin:8px 0 0;color:var(--muted);font-size:10px;line-height:1.55}.pd-incident-meta{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}.pd-incident-chip{padding:5px 7px;border:1px solid var(--line);border-radius:7px;color:var(--quiet);background:rgba(255,255,255,.025);font:8px/1 ui-monospace,SFMono-Regular,Menlo,monospace}.pd-checks{margin:10px 0 0;padding-left:18px;color:var(--muted);font-size:9px;line-height:1.6}.pd-unavailable{display:grid;place-items:center;min-height:42px;color:var(--quiet);font-size:9px}
  .pd-map-stage{overflow:auto;border:1px solid var(--line);border-radius:14px;background:rgba(0,0,0,.22)}.pd-map{display:block;width:100%;min-width:700px;max-height:520px}.pd-map marker path{fill:var(--gold)}.pd-map-edge{fill:none;stroke:var(--violet);stroke-width:2}.pd-map-edge.succeeded{stroke:var(--teal)}.pd-map-edge.failed,.pd-map-edge.looped{stroke:var(--red)}.pd-map-number{fill:var(--gold);font:800 11px/1 ui-monospace,SFMono-Regular,Menlo,monospace;text-anchor:middle}.pd-map-node rect{fill:#171819;stroke:rgba(158,140,255,.45)}.pd-map-node.missing rect{stroke:#777;stroke-dasharray:6 5}.pd-map-node-label{fill:var(--text);font:750 11px/1 sans-serif;text-anchor:middle}.pd-map-node-meta{fill:var(--quiet);font:8px/1 ui-monospace,SFMono-Regular,Menlo,monospace;text-anchor:middle;text-transform:uppercase}.pd-map-edges{display:grid;gap:8px;margin-top:10px}.pd-map-edge-card{display:grid;grid-template-columns:auto minmax(0,1fr);gap:10px;padding:11px;border:1px solid var(--line);border-radius:12px;background:rgba(0,0,0,.18)}.pd-map-index{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;color:#111;background:var(--gold);font:900 9px/1 ui-monospace,SFMono-Regular,Menlo,monospace}.pd-map-edge-title{display:flex;align-items:center;justify-content:space-between;gap:10px;color:var(--text);font-size:10px;font-weight:780}.pd-map-chips{display:flex;gap:5px;flex-wrap:wrap;margin-top:7px}.pd-map-chip{padding:5px 7px;border:1px solid var(--line);border-radius:7px;color:var(--quiet);font:8px/1 ui-monospace,SFMono-Regular,Menlo,monospace}
  body.pd-report-open{overflow:hidden}.pd-report-viewer{position:fixed;inset:0;z-index:1100;display:flex;flex-direction:column;background:var(--bg)}.pd-report-viewer[hidden]{display:none}.pd-report-toolbar{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:14px;min-height:62px;padding:10px 18px;border-bottom:1px solid var(--line);background:rgba(9,10,11,.98)}.pd-report-toolbar-title{color:var(--text);font-size:12px;font-weight:780;text-align:center}.pd-report-toolbar-actions{display:flex;justify-content:flex-end}.pd-report-body{position:relative;flex:1;min-height:0}.pd-report-frame{width:100%;height:100%;border:0;background:#090a0b;opacity:0;transition:opacity .2s}.pd-report-viewer.loaded .pd-report-frame{opacity:1}.pd-report-state{position:absolute;inset:0;z-index:1;display:grid;place-items:center;color:var(--muted);background:#090a0b;font-size:10px}.pd-report-viewer.loaded .pd-report-state{display:none}
  @media(max-width:930px){.pd-layout{grid-template-columns:1fr}.pd-sticky{position:static}.pd-hero{grid-template-columns:1fr}.pd-hero-side{width:max-content}.pd-live{grid-template-columns:1fr}}
  @media(max-width:760px){.pd-filter-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.pd-inspector-layout{grid-template-columns:1fr}}
  @media(max-width:620px){.studio-appbar{flex-wrap:wrap}.studio-appbar-context,.studio-brand-meta{display:none}.studio-actions{width:100%;justify-content:flex-start}.pd-card{padding:17px}.pd-fields,.pd-signals,.pd-filter-grid{grid-template-columns:1fr}.pd-kpis,.pd-coverage{grid-template-columns:repeat(2,minmax(0,1fr))}.pd-toolbar,.pd-recorder-head{align-items:flex-start;flex-direction:column}.pd-range{grid-template-columns:auto 1fr}.pd-range span:last-child{grid-column:2}.pd-report-toolbar{grid-template-columns:1fr 1fr}.pd-report-toolbar-title{display:none}}
</style>
</head>
<body>
<div class="studio-ambient" aria-hidden="true"><span class="studio-orb gold"></span><span class="studio-orb violet"></span><span class="studio-orb teal"></span></div>
<header class="studio-appbar">
  <a class="studio-brand" href="/" style="text-decoration:none"><span class="studio-brand-mark">APS</span><span class="studio-brand-copy"><span class="studio-brand-name">ADB Performance Studio</span><span class="studio-brand-meta">Player Debugger · __BUILD__</span></span></a>
  <div class="studio-appbar-context"></div>
  <nav class="studio-actions" aria-label="Application"><a class="studio-link" href="/">Home</a><a class="studio-link" href="/dashboard">Live dashboard</a><a class="studio-link" href="/release-guard">Release Guard</a></nav>
</header>
<main class="studio-shell">
  <section class="pd-hero studio-enter">
    <div><p class="studio-eyebrow">Offline playback intelligence</p><h1 class="studio-page-title">Follow every player. Explain every fallback.</h1><p class="studio-page-copy">Reconstruct parallel players, delivery changes and failures from passive Android evidence, with optional structured OPTD telemetry when an app adapter is available.</p></div>
    <div class="pd-hero-side">DEVICE + PLAYER + PROJECT AGNOSTIC</div>
  </section>
  <div class="pd-layout studio-enter">
    <aside class="pd-stack pd-sticky">
      <section class="studio-panel pd-card" aria-labelledby="captureTitle">
        <div class="studio-section-head"><div><h2 class="studio-section-title" id="captureTitle">Capture configuration</h2><p class="studio-section-copy">Your draft survives navigation and never leaves this Mac.</p></div><button class="studio-button" type="button" onclick="loadDevices()">Refresh</button></div>
        <div class="pd-fields">
          <div class="pd-field span"><label for="pdDevice">ADB target</label><select id="pdDevice" onchange="probeDevice();saveDraft()"><option value="">Select a connected device</option></select></div>
          <div class="pd-field span"><label for="pdPackage">Android package</label><input id="pdPackage" autocomplete="off" spellcheck="false" placeholder="com.example.player"></div>
          <div class="pd-field"><label for="pdDuration">Duration</label><select id="pdDuration"><option value="300">5 minutes</option><option value="600">10 minutes</option><option value="1800">30 minutes</option><option value="3600">1 hour</option></select></div>
          <div class="pd-field"><label for="pdInterval">Sample interval</label><select id="pdInterval"><option value="0.5">0.5 second</option><option value="1">1 second</option><option value="2">2 seconds</option></select></div>
        </div>
        <div class="pd-divider"></div>
        <div class="pd-label">Default diagnostics</div><p class="pd-hint">Balanced for dev and QA: enough context for playback failures without turning every capture into a system trace.</p>
        <div class="pd-signals">
          <label class="pd-signal"><input id="cpuUtil" type="checkbox" checked><span class="pd-check"></span><span><strong>CPU utilization</strong><small>Whole-device pressure</small></span></label>
          <label class="pd-signal"><input id="perCoreCpu" type="checkbox" checked><span class="pd-check"></span><span><strong>Per-core CPU</strong><small>Core imbalance</small></span></label>
          <label class="pd-signal"><input id="topProcessCpu" type="checkbox" checked><span class="pd-check"></span><span><strong>Top process CPU</strong><small>Competing workloads</small></span></label>
          <label class="pd-signal"><input id="memoryUsed" type="checkbox" checked><span class="pd-check"></span><span><strong>Memory used</strong><small>Capacity trend</small></span></label>
          <label class="pd-signal"><input id="psiPressure" type="checkbox" checked><span class="pd-check"></span><span><strong>PSI pressure stall</strong><small>CPU / memory / I/O stalls</small></span></label>
          <label class="pd-signal"><input id="topProcessMemory" type="checkbox" checked><span class="pd-check"></span><span><strong>Top process memory</strong><small>Largest consumers</small></span></label>
        </div>
        <div class="pd-locked"><span>Logcat playback evidence</span><strong>Required · ON</strong></div>
        <div class="pd-actions"><button class="studio-button primary" id="pdStart" type="button" onclick="startCapture()">Start capture</button><button class="studio-button danger" id="pdStop" type="button" onclick="stopCapture()" disabled>Stop</button></div>
        <div class="pd-message" id="pdMessage" role="status" aria-live="polite"></div>
      </section>
      <section class="studio-panel pd-card" aria-labelledby="historyTitle">
        <div class="pd-toolbar"><div><h2 class="studio-section-title" id="historyTitle">Capture history</h2><p class="studio-section-copy">Local captures and imported support bundles.</p></div><button class="studio-button" type="button" onclick="loadHistory()">Reload</button></div>
        <div class="pd-history" id="pdHistory"><div class="pd-empty">No Player Debugger captures yet.</div></div>
      </section>
    </aside>
    <div class="pd-stack">
      <section class="studio-panel pd-card" aria-labelledby="cockpitTitle">
        <div class="pd-status-head"><div><p class="pd-state" id="pdState">Waiting for capture</p><h2 class="studio-section-title" id="cockpitTitle" style="margin-top:7px">Playback cockpit</h2><p class="studio-section-copy" id="pdStatusCopy">Choose a device and package to begin.</p></div><span class="studio-status" id="pdLiveStatus">Idle</span></div>
        <div class="pd-progress"><span id="pdProgress"></span></div>
        <div class="pd-kpis"><div class="pd-kpi"><b id="eventCount">0</b><span>Events</span></div><div class="pd-kpi"><b id="sessionCount">0</b><span>Sessions</span></div><div class="pd-kpi"><b id="playerCount">0</b><span>Players</span></div><div class="pd-kpi"><b id="handoffCount">0</b><span>Handoffs</span></div></div>
        <div class="pd-coverage" aria-label="Evidence availability"><div class="pd-evidence reported"><i>R</i><span>Reported <b id="reportedCount">0</b></span></div><div class="pd-evidence measured"><i>M</i><span>Measured <b id="measuredCount">0</b></span></div><div class="pd-evidence inferred"><i>I</i><span>Inferred <b id="inferredCount">0</b></span></div><div class="pd-evidence unavailable"><i>—</i><span id="adapterState">Adapter unknown</span></div></div>
        <div class="pd-live"><div class="pd-well"><div class="pd-well-title">Active delivery path</div><div class="pd-path" id="deliveryPath"><span class="pd-node">Waiting for playback evidence</span></div><div class="pd-player-list" id="activePlayers"></div></div><div class="pd-well"><div class="pd-well-title">Highest-priority incident</div><div class="pd-incident" id="topIncident">No incident detected in the current evidence window.</div></div></div>
      </section>
      <section class="studio-panel pd-card pd-detail" id="pdDetail" aria-labelledby="detailTitle">
        <div class="studio-section-head"><div><h2 class="studio-section-title" id="detailTitle">Capture evidence</h2><p class="studio-section-copy" id="detailMeta"></p></div><span class="studio-status ok" id="detailState">Ready</span></div>
        <div class="pd-live"><div class="pd-well"><div class="pd-well-title">Reconstructed path</div><div class="pd-path" id="detailPath"></div><div class="pd-player-list" id="detailPlayers"></div></div><div class="pd-well"><div class="pd-well-title">Incident lens</div><div class="pd-incident" id="detailIncident"></div></div></div>
        <div class="pd-detail-actions"><button class="studio-button" type="button" onclick="reanalyzeSelected()">Re-analyze</button><button class="studio-button" type="button" onclick="previewExport()">Privacy preview</button><button class="studio-button" type="button" onclick="openPlayerReport(this)">Open offline report</button><button class="studio-button primary" type="button" onclick="exportSelected()">Export sanitized bundle</button></div>
        <div class="pd-message" id="detailMessage" role="status" aria-live="polite"></div>
      </section>
      <section class="studio-panel pd-card pd-recorder" id="pdHandoffMap" aria-labelledby="handoffMapTitle">
        <div class="studio-section-head"><div><p class="pd-state">Directed transitions</p><h2 class="studio-section-title" id="handoffMapTitle" style="margin-top:7px">Handoff Map</h2><p class="studio-section-copy">Any player or delivery can transition to any other; missing endpoints stay visible instead of being guessed.</p></div><span class="studio-status" id="handoffMapStatus">No transitions</span></div>
        <div class="pd-map-stage" id="handoffMapCanvas"><div class="pd-empty">No player graph loaded.</div></div>
        <div class="pd-map-edges" id="handoffMapEdges"></div>
      </section>
      <section class="studio-panel pd-card pd-recorder" id="pdRecorder" aria-labelledby="recorderTitle">
        <div class="pd-recorder-head"><div><p class="pd-state">Synchronized evidence</p><h2 class="studio-section-title" id="recorderTitle" style="margin-top:7px">Flight Recorder</h2><p class="studio-section-copy">Every lane shares the same time window, range, filters and selection.</p></div><div class="pd-window-controls"><button class="studio-button" id="timelinePrev" type="button" onclick="previousTimeline()">← Earlier</button><label class="pd-label" for="timelineLimit">Window</label><select id="timelineLimit" onchange="changeTimelineWindow()"><option value="50">50 events</option><option value="100">100 events</option><option value="200" selected>200 events</option><option value="500">500 events</option></select><button class="studio-button" id="timelineNext" type="button" onclick="nextTimeline()">Later →</button></div></div>
        <div class="pd-filter-grid" aria-label="Live Inspector filters">
          <div class="pd-field"><label for="filterSession">Session</label><select id="filterSession" onchange="renderFlightRecorder()"><option value="">All sessions</option></select></div>
          <div class="pd-field"><label for="filterInstance">Player instance</label><select id="filterInstance" onchange="renderFlightRecorder()"><option value="">All players</option></select></div>
          <div class="pd-field"><label for="filterType">Event type</label><input id="filterType" placeholder="buffer, error, frame…" oninput="renderFlightRecorder()"></div>
          <div class="pd-field"><label for="filterSource">Evidence source</label><select id="filterSource" onchange="renderFlightRecorder()"><option value="">All sources</option><option value="APP_REPORTED">Reported</option><option value="DEVICE_MEASURED">Measured</option><option value="LOG_PARSED">Log parsed</option><option value="ENGINE_INFERRED">Inferred</option></select></div>
          <div class="pd-field"><label for="filterConfidence">Minimum confidence</label><select id="filterConfidence" onchange="renderFlightRecorder()"><option value="0">Any confidence</option><option value="0.5">50%</option><option value="0.8">80%</option><option value="0.95">95%</option></select></div>
          <div class="pd-field"><label for="filterText">Search normalized fields</label><input id="filterText" placeholder="decoder, timeout, delivery…" oninput="renderFlightRecorder()"></div>
        </div>
        <div class="pd-range"><span id="rangeStartLabel">0%</span><input id="rangeStart" type="range" min="0" max="100" value="0" aria-label="Visible range start" oninput="changeTimelineRange()"><input id="rangeEnd" type="range" min="0" max="100" value="100" aria-label="Visible range end" oninput="changeTimelineRange()"><span id="rangeEndLabel">100%</span></div>
        <div class="pd-toolbar"><p class="studio-section-copy" id="laneStatus">No timeline loaded.</p><button class="studio-button" type="button" onclick="clearInspectorFilters()">Clear filters</button></div>
        <div class="pd-lanes" id="timelineLanes" role="list" aria-label="Playback evidence timeline"><div class="pd-unavailable">Timeline evidence unavailable.</div></div>
        <div class="pd-inspector-layout">
          <section class="pd-inspector" aria-labelledby="eventInspectorTitle"><div class="pd-well-title">Selected event</div><h3 id="eventInspectorTitle">Select a timeline marker</h3><div class="pd-inspector-meta" id="eventInspectorMeta">Use Left and Right arrows to move between visible events.</div><pre id="eventInspectorBody">Normalized fields will appear here.</pre><div class="pd-evidence-actions" id="eventEvidenceActions"></div></section>
          <section class="pd-inspector" aria-labelledby="rawEvidenceTitle"><div class="pd-well-title">Registered raw evidence</div><h3 id="rawEvidenceTitle">No excerpt selected</h3><div class="pd-inspector-meta" id="rawEvidenceMeta">Only capture-registered text artifacts can be opened.</div><pre id="rawEvidenceBody">Raw evidence stays local to this application.</pre></section>
        </div>
      </section>
      <section class="studio-panel pd-card pd-recorder" id="pdIncidentLens" aria-labelledby="incidentLensTitle">
        <div class="studio-section-head"><div><p class="pd-state">Explainable findings</p><h2 class="studio-section-title" id="incidentLensTitle" style="margin-top:7px">Incident Lens</h2><p class="studio-section-copy">Rules show why they fired, what they affect and which evidence supports them.</p></div><span class="studio-status" id="incidentCountStatus">No findings</span></div>
        <div class="pd-incident-list" id="incidentCards"><div class="pd-empty">No deterministic incidents matched this capture.</div></div>
      </section>
    </div>
  </div>
</main>
<section class="pd-report-viewer" id="playerReportViewer" role="dialog" aria-modal="true" aria-labelledby="playerReportTitle" hidden>
  <div class="pd-report-toolbar"><button class="studio-button" id="playerReportBack" type="button" onclick="closePlayerReport()">← Back to Player Debugger</button><div class="pd-report-toolbar-title" id="playerReportTitle">Offline Player Debugger report</div><div class="pd-report-toolbar-actions"><button class="studio-button primary" type="button" onclick="downloadPlayerReport()">Download HTML</button></div></div>
  <div class="pd-report-body"><div class="pd-report-state" id="playerReportState" role="status" aria-live="polite">Loading the locally generated report…</div><iframe class="pd-report-frame" id="playerReportFrame" title="Offline Player Debugger report" referrerpolicy="no-referrer"></iframe></div>
</section>
<script>
var DRAFT_KEY='aps.playerDebugger.draft.v1',statusTimer=null,currentCapture=null,selectedCapture=null,restored={};
var currentGraph=null,currentIncidents=[],timelinePage={offset:0,nextOffset:null,events:[]},visibleTimelineEvents=[],selectedEventSequence=null,incidentView=[],playerReportTrigger=null,playerReportTimer=null;
var SIGNALS=['cpuUtil','perCoreCpu','topProcessCpu','memoryUsed','psiPressure','topProcessMemory'];
var TIMELINE_LANES=[['sessions','Sessions'],['players','Players'],['handoffs','Handoffs'],['states','States'],['buffer','Buffering'],['first-frame','First frame'],['audio-video','Audio / video'],['quality','Quality'],['errors','Errors'],['performance','Performance'],['snapshots','Snapshots'],['other','Other evidence']];
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function api(url,options){return fetch(url,options).then(function(r){var type=r.headers.get('content-type')||'';if(type.indexOf('application/json')<0){if(!r.ok)throw new Error('Request failed: '+r.status);return r;}return r.json().then(function(b){if(!r.ok||b.ok===false)throw new Error(b.error||('Request failed: '+r.status));return b;});});}
function saveDraft(){var values={pdDevice:document.getElementById('pdDevice').value,pdPackage:document.getElementById('pdPackage').value,pdDuration:document.getElementById('pdDuration').value,pdInterval:document.getElementById('pdInterval').value};SIGNALS.forEach(function(id){values[id]=document.getElementById(id).checked;});localStorage.setItem(DRAFT_KEY,JSON.stringify(values));}
function restoreDraft(){try{restored=JSON.parse(localStorage.getItem(DRAFT_KEY)||'null')||{};['pdPackage','pdDuration','pdInterval'].forEach(function(id){if(restored[id]!=null)document.getElementById(id).value=restored[id];});SIGNALS.forEach(function(id){if(Object.prototype.hasOwnProperty.call(restored,id))document.getElementById(id).checked=!!restored[id];});}catch(e){restored={};}}
function bindDraft(){Array.prototype.forEach.call(document.querySelectorAll('input,select'),function(el){el.addEventListener('change',saveDraft);el.addEventListener('input',saveDraft);});window.addEventListener('beforeunload',saveDraft);}
function message(text,bad){var el=document.getElementById('pdMessage');el.textContent=text||'';el.className='pd-message'+(bad?' bad':'');}
function detailMessage(text,bad){var el=document.getElementById('detailMessage');el.textContent=text||'';el.className='pd-message'+(bad?' bad':'');}
function loadDevices(){return api('/api/devices').then(function(d){var list=(d.devices||[]).filter(function(x){return x.state==='device';}),select=document.getElementById('pdDevice'),wanted=select.value||restored.pdDevice||'';select.innerHTML='<option value="">Select a connected device</option>'+list.map(function(x){return'<option value="'+esc(x.serial)+'">'+esc((x.desc||x.serial)+' · '+x.serial)+'</option>';}).join('');if(wanted&&list.some(function(x){return x.serial===wanted;}))select.value=wanted;probeDevice();}).catch(function(e){message(e.message,true);});}
function probeDevice(){var serial=document.getElementById('pdDevice').value;if(!serial){document.getElementById('adapterState').textContent='Device unavailable';return;}api('/api/player/capabilities?serial='+encodeURIComponent(serial)).then(function(d){var caps=(d.target&&d.target.capabilities)||[];document.getElementById('adapterState').textContent=caps.indexOf('LOGCAT')>=0?'Passive ready':'Limited evidence';}).catch(function(e){message(e.message,true);});}
function startCapture(){var serial=document.getElementById('pdDevice').value,pkg=document.getElementById('pdPackage').value.trim();if(!serial||!pkg){message('Select a device and enter the Android package.',true);return;}var body={serial:serial,packageName:pkg,durationSec:Number(document.getElementById('pdDuration').value),intervalSec:Number(document.getElementById('pdInterval').value)};SIGNALS.forEach(function(id){body[id]=document.getElementById(id).checked;});saveDraft();api('/api/player/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(function(d){currentCapture=d.captureId;message('Capture started. Reproduce the playback issue now.');setRunning(true);pollStatus();}).catch(function(e){message(e.message,true);});}
function stopCapture(){api('/api/player/stop',{method:'POST'}).then(function(){message('Stopping safely and preserving captured evidence…');}).catch(function(e){message(e.message,true);});}
function setRunning(on){document.getElementById('pdStart').disabled=on;document.getElementById('pdStop').disabled=!on;var s=document.getElementById('pdLiveStatus');s.textContent=on?'Live':'Idle';s.className='studio-status '+(on?'ok':'');}
function progressFor(state){return{SELECT:2,PROBE:8,READY:15,CAPTURING:55,FINALIZING:75,ANALYZING:88,COMPLETE:100,PARTIAL:100,CANCELLED:100,FAILED:100}[state]||4;}
function pollStatus(){if(statusTimer)clearTimeout(statusTimer);api('/api/player/status').then(function(d){renderStatus(d);if(d.running){statusTimer=setTimeout(pollStatus,700);}else{setRunning(false);loadHistory();if(currentCapture)loadCapture(currentCapture);}}).catch(function(e){message(e.message,true);statusTimer=setTimeout(pollStatus,1600);});}
function renderStatus(d){var p=d.progress||{},g=d.graph||{};document.getElementById('pdState').textContent=(p.state||'SELECT').replace(/_/g,' ');document.getElementById('pdStatusCopy').textContent=p.message||'Waiting';document.getElementById('pdProgress').style.width=progressFor(p.state)+'%';document.getElementById('eventCount').textContent=p.eventCount||g.events||0;document.getElementById('sessionCount').textContent=g.viewingSessions||0;document.getElementById('playerCount').textContent=g.players||0;document.getElementById('handoffCount').textContent=g.handoffs||0;if(d.highestSeverity){document.getElementById('topIncident').innerHTML='<strong>'+esc(d.highestSeverity)+' incident detected</strong>Open the completed capture for linked evidence and suggested checks.<span class="pd-severity">'+esc(d.highestSeverity)+'</span>';}}
function loadHistory(){return api('/api/player/captures').then(function(d){var list=d.captures||[],el=document.getElementById('pdHistory');if(!list.length){el.innerHTML='<div class="pd-empty">No Player Debugger captures yet.</div>';return;}el.innerHTML=list.map(function(c){return'<button class="pd-run" type="button" onclick="loadCapture(\''+esc(c.captureId)+'\')"><span><strong>'+esc(c.packageName)+'</strong><small>'+esc(c.updatedAt)+' · '+esc(c.captureId)+'</small></span><span class="pd-run-state">'+esc(c.state)+'</span></button>';}).join('');});}
function loadCapture(id){
  selectedCapture=id;selectedEventSequence=null;detailMessage('Loading evidence…');
  ['pdDetail','pdHandoffMap','pdRecorder','pdIncidentLens'].forEach(function(x){document.getElementById(x).classList.add('show');});
  var limit=Number(document.getElementById('timelineLimit').value||200);
  return Promise.all([api('/api/player/graph?captureId='+encodeURIComponent(id)),api('/api/player/incidents?captureId='+encodeURIComponent(id)),api('/api/player/timeline?captureId='+encodeURIComponent(id)+'&limit='+limit)]).then(function(all){
    currentGraph=all[0];currentIncidents=all[1]||[];timelinePage=all[2]||{offset:0,nextOffset:null,events:[]};
    renderCapture();renderHandoffMap();populateInspectorFilters();renderFlightRecorder();renderIncidentLens();detailMessage('');
  }).catch(function(e){detailMessage(e.message,true);renderUnavailableTimeline(e.message);});
}
function renderCapture(){
  var graph=currentGraph||{},incidents=currentIncidents,timeline=timelinePage,summary=graph.summary||{},sessions=graph.viewingSessions||[],players=[];
  sessions.forEach(function(s){(s.playerInstances||[]).forEach(function(p){players.push(p);});});
  document.getElementById('detailMeta').textContent=selectedCapture+' · '+(summary.events||0)+' events · '+sessions.length+' viewing session(s)';
  document.getElementById('detailPlayers').innerHTML=players.length?players.map(function(p){return'<span class="pd-player">'+esc(p.family||p.implementation||'Generic player')+' · '+esc(p.delivery||'unknown delivery')+'</span>';}).join(''):'<span class="pd-player">Player identity unavailable</span>';
  renderPath(document.getElementById('detailPath'),sessions,players);
  var top=incidents.slice().sort(function(a,b){return severity(b.severity)-severity(a.severity);})[0];
  document.getElementById('detailIncident').innerHTML=top?'<strong>'+esc(top.title)+'</strong>'+esc(top.evidence&&top.evidence.explanation)+'<span class="pd-severity">'+esc(top.severity)+' · '+Math.round((top.confidence||0)*100)+'% confidence</span>':'No deterministic incident matched this evidence.';
  var counts={APP_REPORTED:0,DEVICE_MEASURED:0,ENGINE_INFERRED:0};(timeline.events||[]).forEach(function(e){if(counts[e.source]!=null)counts[e.source]++;});
  document.getElementById('reportedCount').textContent=counts.APP_REPORTED;document.getElementById('measuredCount').textContent=counts.DEVICE_MEASURED;document.getElementById('inferredCount').textContent=counts.ENGINE_INFERRED;document.getElementById('adapterState').textContent=counts.APP_REPORTED?'Structured OPTD':'Passive only';
  document.getElementById('eventCount').textContent=summary.events||0;document.getElementById('sessionCount').textContent=summary.viewingSessions||0;document.getElementById('playerCount').textContent=summary.players||0;document.getElementById('handoffCount').textContent=summary.handoffs||0;
  renderPath(document.getElementById('deliveryPath'),sessions,players);document.getElementById('activePlayers').innerHTML=document.getElementById('detailPlayers').innerHTML;
}
function severity(s){return{INFO:1,WARNING:2,CRITICAL:3}[s]||0;}
function renderPath(el,sessions,players){var path=[];sessions.forEach(function(s){(s.handoffs||[]).forEach(function(h){var a=players.filter(function(p){return p.id===h.sourceInstanceId;})[0],b=players.filter(function(p){return p.id===h.targetInstanceId;})[0];if(a)path.push(a.delivery||a.family||'player');if(b)path.push(b.delivery||b.family||'player');});});if(!path.length)path=players.map(function(p){return p.delivery||p.family||'player';});path=path.filter(function(x,i){return i===0||x!==path[i-1];});el.innerHTML=path.length?path.map(function(x,i){return(i?'<span class="pd-arrow">→</span>':'')+'<span class="pd-node">'+esc(x)+'</span>';}).join(''):'<span class="pd-node">No delivery path available</span>';}
function renderHandoffMap(){
  var sessions=(currentGraph&&currentGraph.viewingSessions)||[],nodes=[],edges=[],nodeByKey={};
  function addNode(key,label,role,missing){if(nodeByKey[key])return;var node={key:key,label:label||'Generic player',role:role||'UNKNOWN',missing:!!missing};nodeByKey[key]=node;nodes.push(node);}
  sessions.forEach(function(session){var prefix=session.id+'::';(session.playerInstances||[]).forEach(function(player,index){addNode(prefix+player.id,player.delivery||player.family||player.implementation||('Player '+(index+1)),player.role,false);});(session.handoffs||[]).forEach(function(handoff){var from=handoff.sourceInstanceId?prefix+handoff.sourceInstanceId:prefix+'missing-source-'+handoff.id,to=handoff.targetInstanceId?prefix+handoff.targetInstanceId:prefix+'missing-target-'+handoff.id;addNode(from,'Unknown source','UNKNOWN',true);addNode(to,'Unknown target','UNKNOWN',true);edges.push({handoff:handoff,from:from,to:to,incidents:currentIncidents.filter(function(i){return i.handoffId===handoff.id;}).length});});});
  var canvas=document.getElementById('handoffMapCanvas'),list=document.getElementById('handoffMapEdges'),status=document.getElementById('handoffMapStatus');status.textContent=edges.length?nodes.length+' nodes · '+edges.length+' transition'+(edges.length===1?'':'s'):'No transitions';
  if(!nodes.length){canvas.innerHTML='<div class="pd-empty">No player instances or handoffs were reconstructed.</div>';list.innerHTML='';return;}
  var columns=Math.min(4,Math.max(1,nodes.length)),rows=Math.ceil(nodes.length/columns),width=960,height=Math.max(220,80+rows*130),positions={};nodes.forEach(function(node,index){positions[node.key]={x:120+(index%columns)*230,y:72+Math.floor(index/columns)*130};});
  function boundary(from,to){var dx=to.x-from.x,dy=to.y-from.y;if(dx===0&&dy===0)return{x:from.x,y:from.y};var scale=Math.min(dx===0?Number.MAX_VALUE:82/Math.abs(dx),dy===0?Number.MAX_VALUE:31/Math.abs(dy));return{x:Math.round(from.x+dx*scale),y:Math.round(from.y+dy*scale)};}
  var paths=edges.map(function(edge,index){var a=positions[edge.from],b=positions[edge.to],result=String(edge.handoff.result||'UNKNOWN').toLowerCase();if(edge.from===edge.to)return'<path class="pd-map-edge '+esc(result)+'" d="M '+(a.x+55)+' '+(a.y-31)+' C '+(a.x+115)+' '+(a.y-105)+', '+(a.x-115)+' '+(a.y-105)+', '+(a.x-55)+' '+(a.y-31)+'" marker-end="url(#pdArrow)"/><text class="pd-map-number" x="'+a.x+'" y="'+(a.y-82)+'">'+(index+1)+'</text>';var start=boundary(a,b),end=boundary(b,a),mx=(a.x+b.x)/2,my=(a.y+b.y)/2-14-(index%2)*12;return'<path class="pd-map-edge '+esc(result)+'" d="M '+start.x+' '+start.y+' Q '+mx+' '+my+' '+end.x+' '+end.y+'" marker-end="url(#pdArrow)"/><text class="pd-map-number" x="'+mx+'" y="'+(my-5)+'">'+(index+1)+'</text>';}).join('');
  var nodeSvg=nodes.map(function(node){var p=positions[node.key],label=node.label.length>22?node.label.slice(0,21)+'…':node.label;return'<g class="pd-map-node'+(node.missing?' missing':'')+'" transform="translate('+(p.x-82)+' '+(p.y-31)+')"><title>'+esc(node.label)+' · '+esc(String(node.role).toLowerCase())+'</title><rect width="164" height="62" rx="14"/><text class="pd-map-node-label" x="82" y="27">'+esc(label)+'</text><text class="pd-map-node-meta" x="82" y="45">'+esc(String(node.role).toLowerCase())+'</text></g>';}).join('');
  canvas.innerHTML='<svg class="pd-map" viewBox="0 0 '+width+' '+height+'" role="img" aria-label="Directed player handoff map"><defs><marker id="pdArrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="currentColor"/></marker></defs>'+paths+nodeSvg+'</svg>';
  list.innerHTML=edges.length?edges.map(function(edge,index){var h=edge.handoff,from=nodeByKey[edge.from].label,to=nodeByKey[edge.to].label,duration=h.activatedAtNs==null?'Unavailable':formatNs(h.activatedAtNs-h.requestedAtNs),overlap=h.activatedAtNs!=null&&h.sourceReleasedAtNs!=null?formatNs(Math.max(0,h.sourceReleasedAtNs-h.activatedAtNs)):'Unavailable';return'<article class="pd-map-edge-card"><span class="pd-map-index">'+(index+1)+'</span><div><div class="pd-map-edge-title"><span>'+esc(from)+' → '+esc(to)+'</span><span>'+esc(String(h.result||'UNKNOWN').toLowerCase())+'</span></div><div class="pd-map-chips"><span class="pd-map-chip">Reason · '+esc(h.reason||'Unavailable')+'</span><span class="pd-map-chip">Activation · '+duration+'</span><span class="pd-map-chip">Overlap · '+overlap+'</span><span class="pd-map-chip">Incidents · '+edge.incidents+'</span></div></div></article>';}).join(''):'<div class="pd-empty">Players were observed, but no handoff transitions were recorded.</div>';
}
function formatNs(value){return(Number(value||0)/1000000000).toFixed(2)+' s';}
function laneFor(event){
  var type=String(event.type||'').toLowerCase(),measurements=Object.keys(event.measurements||{}).join(' ').toLowerCase();
  if(type.indexOf('session.')===0)return'sessions';
  if(type.indexOf('handoff')>=0||type.indexOf('fallback')>=0)return'handoffs';
  if(type.indexOf('error')>=0||type.indexOf('crash')>=0||type.indexOf('anr')>=0||type.indexOf('failure')>=0)return'errors';
  if(type.indexOf('player.')===0||type.indexOf('process.')===0||type.indexOf('app.')===0)return'players';
  if(type.indexOf('state')>=0)return'states';
  if(type.indexOf('buffer')>=0)return'buffer';
  if(type.indexOf('first_frame')>=0||type.indexOf('first.frame')>=0||type.indexOf('video.available')>=0)return'first-frame';
  if(type.indexOf('snapshot')>=0||type.indexOf('dumpsys')>=0)return'snapshots';
  if(type.indexOf('audio')>=0||type.indexOf('video')>=0||type.indexOf('render')>=0||type.indexOf('surface')>=0)return'audio-video';
  if(type.indexOf('quality')>=0||type.indexOf('bitrate')>=0||type.indexOf('dropped')>=0||type.indexOf('decoder.stall')>=0)return'quality';
  if(type.indexOf('metric')>=0||/(cpu|memory|psi|network|thermal|load|process)/.test(type+' '+measurements))return'performance';
  return'other';
}
function populateInspectorFilters(){
  var graph=currentGraph||{},sessions=graph.viewingSessions||[],players=[];sessions.forEach(function(s){(s.playerInstances||[]).forEach(function(p){players.push(p);});});
  setFilterOptions('filterSession','All sessions',sessions.map(function(s){return{id:s.id,label:s.contentLabel||s.id};}));
  setFilterOptions('filterInstance','All players',players.map(function(p){return{id:p.id,label:(p.family||p.implementation||p.id)+' · '+(p.delivery||'unknown')};}));
}
function setFilterOptions(id,empty,items){var el=document.getElementById(id),value=el.value;el.innerHTML='<option value="">'+esc(empty)+'</option>'+items.map(function(x){return'<option value="'+esc(x.id)+'">'+esc(x.label)+'</option>';}).join('');if(items.some(function(x){return x.id===value;}))el.value=value;}
function changeTimelineRange(){var a=Number(document.getElementById('rangeStart').value),b=Number(document.getElementById('rangeEnd').value);document.getElementById('rangeStartLabel').textContent=Math.min(a,b)+'%';document.getElementById('rangeEndLabel').textContent=Math.max(a,b)+'%';renderFlightRecorder();}
function clearInspectorFilters(){['filterSession','filterInstance','filterType','filterSource','filterText'].forEach(function(id){document.getElementById(id).value='';});document.getElementById('filterConfidence').value='0';document.getElementById('rangeStart').value='0';document.getElementById('rangeEnd').value='100';changeTimelineRange();}
function sourceClass(source){return{APP_REPORTED:'reported',DEVICE_MEASURED:'measured',ENGINE_INFERRED:'inferred',LOG_PARSED:'parsed'}[source]||'parsed';}
function sourceLetter(source){return{APP_REPORTED:'R',DEVICE_MEASURED:'M',ENGINE_INFERRED:'I',LOG_PARSED:'L'}[source]||'?';}
function renderFlightRecorder(){
  var all=(timelinePage.events||[]).slice().sort(function(a,b){return a.timeNs-b.timeNs||a.sequence-b.sequence;}),start=Number(document.getElementById('rangeStart').value),end=Number(document.getElementById('rangeEnd').value),low=Math.min(start,end),high=Math.max(start,end);
  var first=all.length?all[0].timeNs:0,last=all.length?all[all.length-1].timeNs:first+1,span=Math.max(1,last-first),rangeFirst=first+span*low/100,rangeLast=first+span*high/100;
  var session=document.getElementById('filterSession').value,instance=document.getElementById('filterInstance').value,type=document.getElementById('filterType').value.trim().toLowerCase(),source=document.getElementById('filterSource').value,minConfidence=Number(document.getElementById('filterConfidence').value||0),text=document.getElementById('filterText').value.trim().toLowerCase();
